        width: 100%;
      }
    }
  </style>
</head>
<body>
  <main>
    <section class="quiz-card" aria-labelledby="quiz-title">
      <p class="eyebrow">Multi-select quiz</p>
      <h1 id="quiz-title">Computer Languages</h1>
      <p class="intro">Choose every answer that applies. Some questions have more than one correct choice.</p>

      <form id="language-quiz">
        <div class="form-field">
          <div class="question-header">
            <span class="question-kicker">Question 1</span>
            <p class="question-title" id="question-1">Which of these are commonly considered programming languages?</p>
            <p class="help-text">Select all languages used to write instructions that a computer can execute or interpret.</p>
          </div>
          <fieldset class="choices" aria-labelledby="question-1">
            <label class="choice">
              <input type="checkbox" name="q1" value="Python">
              Python
            </label>
            <label class="choice">
              <input type="checkbox" name="q1" value="HTML">
              HTML
            </label>
            <label class="choice">
              <input type="checkbox" name="q1" value="JavaScript">
              JavaScript
            </label>
            <label class="choice">
              <input type="checkbox" name="q1" value="CSS">
              CSS
            </label>
          </fieldset>
        </div>

        <div class="form-field">
          <div class="question-header">
            <span class="question-kicker">Question 2</span>
            <p class="question-title" id="question-2">Which languages are often used for web development?</p>
          </div>
          <fieldset class="choices" aria-labelledby="question-2">
            <label class="choice">
              <input type="checkbox" name="q2" value="JavaScript">
              JavaScript
            </label>
            <label class="choice">
              <input type="checkbox" name="q2" value="PHP">
              PHP
            </label>
            <label class="choice">
              <input type="checkbox" name="q2" value="SQL">
              SQL
            </label>
            <label class="choice">
              <input type="checkbox" name="q2" value="COBOL">
              COBOL
            </label>
          </fieldset>
        </div>

        <div class="form-field">
          <div class="question-header">
            <span class="question-kicker">Question 3</span>
            <p class="question-title" id="question-3">Which languages are known for strong use in systems programming?</p>
          </div>
          <fieldset class="choices" aria-labelledby="question-3">
            <label class="choice">
              <input type="checkbox" name="q3" value="C">
              C
            </label>
            <label class="choice">
              <input type="checkbox" name="q3" value="Rust">
              Rust
            </label>
            <label class="choice">
              <input type="checkbox" name="q3" value="Swift">
              Swift
            </label>
            <label class="choice">
              <input type="checkbox" name="q3" value="Assembly">
              Assembly
            </label>
          </fieldset>
        </div>

        <div class="actions">
          <button type="submit">Submit answers</button>
          <p class="status" id="quiz-status" role="status" aria-live="polite">No answers submitted yet.</p>
        </div>
      </form>
    </section>
  </main>

  <script>
    const form = document.querySelector("#language-quiz");
    const status = document.querySelector("#quiz-status");

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const selectedCounts = ["q1", "q2", "q3"].map((name) => {
        return form.querySelectorAll(`input[name="${name}"]:checked`).length;
      });
      const totalSelected = selectedCounts.reduce((sum, count) => sum + count, 0);

      status.textContent = totalSelected === 0
        ? "Select at least one answer before submitting."
        : `Submitted ${totalSelected} answer${totalSelected === 1 ? "" : "s"} across 3 questions.`;
    });
  </script>
</body>
</html>
